-- Analysis of the Jeans And Tops and Indo Western jewellery sets, one JSON document per set, into public.catalogue_analysis.
--
-- Source: the styles folder next to each set's originals ("<set> jew 400/styles/N.J.json"). A record is matched to its
-- catalogue row by name and category, as the catalogue numbers these sets:   style "12.J" -> 'Jewellery 12', category as below.
--   Jeans And Tops: 20 records (1..20)      Indo Western: 24 records (1..25, no 7)
--
-- Stops and rolls everything back if a record has no catalogue row. Re-running updates the same rows.

alter table public.catalogue_analysis drop constraint if exists catalogue_analysis_category;
alter table public.catalogue_analysis add constraint catalogue_analysis_category
  check (category is null or category in ('Saree', 'Lehenga', 'Kurti', 'Jeans And Tops', 'Indo Western'));

create temp table _staged (
  category  text not null,
  num       integer not null,
  drive_id  text not null,
  doc       jsonb not null
) on commit drop;


do $$
declare missing text;
begin
  select string_agg(s.category || ' ' || s.drive_id, ', ') into missing
  from _staged s
  left join public.jewellery j on j.name = 'Jewellery ' || s.num and j.category = s.category
  where j.id is null;
  if missing is not null then
    raise exception 'No catalogue row for these analysis records: %', missing;
  end if;
end
$$;

select j.id, s.drive_id, s.category, s.doc
from _staged s
join public.jewellery j on j.name = 'Jewellery ' || s.num and j.category = s.category
on conflict (jewellery_id) where jewellery_id is not null
do update set drive_id = excluded.drive_id, category = excluded.category, analysis = excluded.analysis, analysed_at = now();
